from pathlib import Path
import json
p=Path('11_Проект_Сбер/3_итерация/greenwashing/03_итерация_3_пайплайн/outputs/gazprom_2023_deepseek');data=json.loads((p/'review_data.json').read_text())
for r in data:r['images']=[str(x.relative_to(p))for x in sorted((p/'images').glob(r['id']+'_*.png'))]
blob=json.dumps(data,ensure_ascii=False).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
head='''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Газпром 2023 · Сравнение PDF → Markdown</title>
<style>
*{box-sizing:border-box}body{font:15px/1.55 Arial,sans-serif;color:#17212b;background:#f6f8fa;margin:0}header,main{max-width:1600px;margin:auto;padding:22px}h1{font-size:25px;margin:0 0 8px}h2{font-size:20px}h3{font-size:17px}.muted{color:#556473}.controls{display:flex;gap:10px;align-items:center;flex-wrap:wrap;position:sticky;top:0;background:#fff;padding:12px;border:1px solid #d8e0e7;z-index:2}button,select{font:inherit;padding:8px 12px;border:1px solid #aebbc7;border-radius:5px;background:#fff;color:#17212b;max-width:100%}button{cursor:pointer}button:hover{background:#edf3f8}.grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:18px;margin:18px 0}.pane{background:white;border:1px solid #d8e0e7;min-width:0}.label{padding:12px 16px;background:#eaf0f5;border-bottom:1px solid #d8e0e7;font-weight:bold}.rendered{padding:16px;overflow-wrap:anywhere;overflow-x:auto}.rendered table{border-collapse:collapse;font-size:13px;display:block;overflow-x:auto;max-width:100%;margin:14px 0;white-space:normal}.rendered th,.rendered td{border:1px solid #bcc9d4;padding:7px 9px;vertical-align:top;min-width:70px}.rendered td,.rendered th{overflow-wrap:normal;word-break:normal}.rendered th{background:#edf3f8}.rendered tr:nth-child(even){background:#f7f9fb}.rendered p{margin:10px 0}.rendered sup{font-size:.72em}.rendered pre,pre{white-space:pre-wrap;overflow-wrap:anywhere;font:12px/1.5 ui-monospace,monospace}details{background:white;border:1px solid #d8e0e7;padding:12px;margin:12px 0}summary{cursor:pointer;font-weight:bold}.status{margin:12px 0;padding:12px;background:#fff6df;border:1px solid #e5cd8e}.sources{display:grid;gap:12px;grid-template-columns:repeat(auto-fit,minmax(280px,1fr))}.sources img{max-width:100%;height:auto;border:1px solid #ddd}a{color:#16579a}.raw{max-height:600px;overflow:auto}#stats{margin:12px 0}footer{padding:20px;color:#556473}@media(max-width:760px){header,main{padding:12px}.grid{grid-template-columns:minmax(0,1fr)}h1{font-size:21px}.controls{position:static}.rendered{padding:12px}.sources{grid-template-columns:1fr}.rendered table{min-width:800px;max-width:none;width:max-content}.rendered td,.rendered th{max-width:340px}.rendered table:before{content:none}}
</style>
<header><h1>Газпром 2023: локальная версия и DeepSeek</h1><div class="muted">Посимвольное сравнение всех страниц. Различие текста не доказывает ошибку: окончательное основание — исходный PDF.</div></header>
<main><div class="controls"><label>Отчёт <select id="report"><option value="all">Оба отчёта</option><option value="social">Социальный</option><option value="environment">Экологический</option></select></label><button id="prev">←</button><select id="page" aria-label="Выбор страницы"></select><button id="next">→</button><button id="source">Показать оригинал</button><select id="view" aria-label="Показывать версию"><option value="both">Обе версии</option><option value="local">Локальная</option><option value="deepseek">DeepSeek</option></select><a href="README.md">Выводы и ограничения</a></div>
<div id="stats"></div><div class="muted">На узком экране широкие таблицы прокручиваются горизонтально. Версию можно выбрать в меню.</div><div class="status">Это сравнение машинных/адресно исправленных транскрипций. Полная посимвольная экспертная приёмка исходных PDF не заявляется.</div>
<div id="sources" hidden></div><div class="grid"><section class="pane" id="localpane"><div class="label">Локально · исходная версия для сравнения</div><div id="left" class="rendered"></div></section><section class="pane" id="deepseekpane"><div class="label" id="rightlabel">DeepSeek</div><div id="right" class="rendered"></div></section></div>
<details><summary>Строковые изменения для чтения</summary><div id="diff" class="rendered raw"></div></details>
<details><summary>Исходный Markdown</summary><div class="grid"><pre id="rawleft" class="raw"></pre><pre id="rawright" class="raw"></pre></div></details><p id="charlink"></p>
</main><footer>Все стили, тексты и логика локальны; CDN и внешние запросы для просмотра не нужны. Изображения берутся из папки images рядом.</footer>'''
script='''<script>
const data=JSON.parse(document.getElementById('data').textContent);let items=data;
const report=document.getElementById('report'),page=document.getElementById('page');
function draw(){const r=items[Number(page.value)||0];if(!r)return;document.getElementById('left').innerHTML=r.left||'<p class="muted">В этом варианте нет текстового содержимого. Оригинал доступен по кнопке выше.</p>';document.getElementById('right').innerHTML=r.right||'<p class="muted">Модель вернула пустой текст. Оригинал доступен по кнопке выше.</p>';document.getElementById('diff').innerHTML=r.diff;document.getElementById('rawleft').textContent=r.raw_left;document.getElementById('rawright').textContent=r.raw_right;document.getElementById('rightlabel').textContent='DeepSeek · '+({'v1':'первый проход','v2':'повторный проход','source_checked_patch':'адресная правка по PDF'}[r.version]||r.version);document.getElementById('stats').textContent=(r.report==='social'?'Социальный':'Экологический')+' отчёт · PDF-страница '+r.page+' · '+r.stats.baseline_chars+' → '+r.stats.deepseek_chars+' символов · расстояние редактирования '+r.stats.raw_char_distance+' (не число фактических ошибок)';document.getElementById('charlink').innerHTML='<a href="char_diff/'+r.id+'_selected.json">Точный посимвольный протокол Unicode</a>';const s=document.getElementById('sources');s.innerHTML='<div class="sources">'+r.images.map(u=>'<img loading="lazy" src="'+u+'" alt="Исходный PDF: '+r.id+'">').join('')+'</div>';window.currentPage=r.id;window.scrollTo(0,0);}
function filter(){items=report.value==='all'?data:data.filter(r=>r.report===report.value);page.innerHTML=items.map((r,i)=>'<option value="'+i+'">'+(r.report==='social'?'Социальный':'Экологический')+' · '+r.page+'</option>').join('');draw();}
report.addEventListener('change',filter);page.addEventListener('change',draw);document.getElementById('prev').onclick=()=>{page.value=Math.max(0,Number(page.value)-1);draw()};document.getElementById('next').onclick=()=>{page.value=Math.min(items.length-1,Number(page.value)+1);draw()};document.getElementById('source').onclick=()=>{const s=document.getElementById('sources');s.hidden=!s.hidden};window.showPage=id=>{report.value='all';filter();page.value=data.findIndex(r=>r.id===id);draw()};document.getElementById('view').onchange=()=>{const v=document.getElementById('view').value;document.getElementById('localpane').hidden=v==='deepseek';document.getElementById('deepseekpane').hidden=v==='local';document.querySelector('.grid').style.gridTemplateColumns=v==='both'?'':'minmax(0,1fr)';window.scrollTo(0,0)};window.reviewData=data;filter();
</script></html>'''
(p/'review.html').write_text(head+'<script id="data" type="application/json">'+blob+'</script>'+script)
print('HTML built:',len(data),'pages', (p/'review.html').stat().st_size,'bytes')
